            return resp.status, dict(resp.headers), resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")

def get_token():
    while True:
        s, h, b = req("POST", "/token")
        if s == 200:
            return json.loads(b)["token"]
        log.write(f"token {s} {b[:200]}\n"); log.flush()
        time.sleep(float(h.get("Retry-After", 1)))

token = get_token()
token_fetches = 1

def authed_get(path):
    """GET with retry: 429 -> wait Retry-After; 401 -> new token; 5xx/other -> retry."""
    global token, token_fetches
    attempts = 0
    while True:
        attempts += 1
        s, h, b = req("GET", path, token)
        if s == 200:
            return json.loads(b)
        log.write(f"{path} attempt {attempts} status {s} headers={ {k:v for k,v in h.items() if k.lower() in ('retry-after','www-authenticate')} } body={b[:200]}\n"); log.flush()
        if s == 404:
            return None
        if s == 401:
            token = get_token(); token_fetches += 1
        elif s == 429:
            time.sleep(float(h.get("Retry-After", 1)))
        else:
            time.sleep(min(2 ** attempts, 30))
        if attempts > 200:
            raise SystemExit(f"giving up on {path}")

pages = []
first = authed_get("/orders?page=1")
total = first["total_pages"]
pages.append(first)
print("total_pages", total, "first next", first["next"], file=sys.stderr)
for n in range(2, total + 1):
    p = authed_get(f"/orders?page={n}")
    pages.append(p)
    if p["next"] is None and n != total:
        log.write(f"page {n} next null before total {total}\n")

items = [it for p in pages for it in p["items"]]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
print("pages", len(pages), "raw items", len(items), "token_fetches", token_fetches, file=sys.stderr)
