import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
log = open("/tmp/recon/log2.txt", "w")

def req(method, path, token=None):
    headers = {"Authorization": f"Bearer {token}"} if token else {}
    r = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(r, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")

def get_token():
    while True:
        s, h, b = req("POST", "/token")
        if s == 200: return json.loads(b)["token"]
        time.sleep(float(h.get("Retry-After", 1)))

token = get_token()
def customer(cid):
    global token
    n = 0
    while True:
        n += 1
        s, h, b = req("GET", f"/customers/{cid}", token)
        if s == 200: return json.loads(b)
        log.write(f"{cid} attempt {n} status {s} body={b[:200]}\n"); log.flush()
        if s == 404: return None
        if s == 401: token = get_token()
        elif s == 429: time.sleep(float(h.get("Retry-After", 1)))
        else: time.sleep(min(2 ** n, 30))
        if n > 200: raise SystemExit(f"giving up on {cid}")

pages = json.load(open("/tmp/recon/pages.json"))
seen = {}
dups = 0
for p in pages:
    for it in p["items"]:
        if it["id"] in seen:
            dups += 1
            assert seen[it["id"]] == it, it["id"]
        else:
            seen[it["id"]] = it

START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: covers 31 May inclusive
qual = []
for it in seen.values():
    if it["status"] != "shipped": continue
    t = datetime.fromisoformat(it["placed_at"]).astimezone(timezone.utc)
    if START <= t < END: qual.append(it)

cust_ids = sorted({it["customer_id"] for it in qual})
custs = {}
for cid in cust_ids:
    c = customer(cid)
    assert c is not None, f"unknown customer {cid}"
    custs[cid] = c
print("qualifying orders", len(qual), "distinct customers", len(cust_ids), file=__import__('sys').stderr)

by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
for it in qual:
    c = custs[it["customer_id"]]
    amt = Decimal(it["amount_cents"]) * (100 - c["discount_pct"]) / 100
    rounded = int(amt.quantize(Decimal(1), rounding=ROUND_HALF_UP))
    by_region[c["region"]] += rounded

total = sum(by_region.values())
result = {"total_cents": total, "order_count": len(qual), "duplicates_skipped": dups, "by_region": by_region}
json.dump(result, open("/tmp/recon/result.json", "w"), indent=2)
print(json.dumps(result, indent=2))
EOF
python3 -I compute.py; echo "exit $?"; cat log2.txt | head

